import{_ as e,o as s,c as l,a5 as r}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse(`{"title":"运行计时器","description":"let ticksInterval self.addEventListener('message', function (ev) \\\\{ const handlers \\\\{ startTicks: (data) \\\\ \\\\{ ticksInterval setInterval(() \\\\。","frontmatter":{"title":"运行计时器","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","进阶语言能力"],"description":"let ticksInterval self.addEventListener('message', function (ev) \\\\{ const handlers \\\\{ startTicks: (data) \\\\ \\\\{ ticksInterval setInterval(() \\\\。","sidebarWeight":43,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/webworkers/应用/运行计时器.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/07-进阶语言能力/应用/运行计时器.md","filePath":"posts/JavaScript系统教程/07-进阶语言能力/应用/运行计时器.md"}`),i={name:"posts/JavaScript系统教程/07-进阶语言能力/应用/运行计时器.md"};function a(n,t,o,g,c,p){return s(),l("div",null,[...t[0]||(t[0]=[r('<div><h1 id="运行计时器" tabindex="-1">运行计时器 <a class="header-anchor" href="#运行计时器" aria-label="Permalink to &quot;运行计时器&quot;">​</a></h1><blockquote><p>本节目标：理解“运行计时器”的核心思路，并能把它用于实际开发或面试表达。 let ticksInterval self.addEventListener(&#39;message&#39;, function (ev) { const handlers = { startTicks: (data) =&gt; { ticksInterval = setInterval(() =&gt; { self.postMessage({ type: &#39;tick&#39; }) }, data.delay) }, stopTicks: () =&gt; { clearInterval(ticksInterval) } } if (handlers[ev.data.type]) { handlers<a href="./ev.data">ev.data.type</a> } }, false);</p></blockquote><p>这段代码是一个运行在 <strong>Web Worker</strong> 环境中的 JavaScript 脚本，用于管理一个定时器（setInterval），并通过 postMessage API 与主线程通信。 概述 该代码运行在一个 <strong>Web Worker</strong> 中，Web Worker 是 JavaScript 提供的一种机制，允许脚本在后台线程运行，避免阻塞主线程的界面操作。代码的功能是：</p><ol><li>监听主线程发送的消息（通过 postMessage）。</li><li>根据消息类型执行操作：启动或停止一个定时器。</li><li>定时器通过 setInterval 定期向主线程发送“tick”消息。</li></ol><p>代码使用一个 ticksInterval 变量保存 setInterval 的引用，并定义了两个处理函数：startTicks 用于启动定时器，stopTicks 用于停止定时器。主线程通过消息控制这些操作。</p><p><strong>代码逐行解析</strong><strong>1. 变量声明</strong> let ticksInterval</p><ul><li><strong>ticksInterval</strong>：使用 let 声明的变量，用于存储 setInterval 返回的定时器 ID。初始值为 undefined，在调用 setInterval 时会被赋值，用于后续停止定时器。</li></ul><p><strong>2. 消息事件监听</strong> self.addEventListener(&#39;message&#39;, function(ev) { ... }, false);</p><ul><li><strong>self</strong>：指向 Web Worker 的全局作用域（相当于主线程中的 window）。</li><li><strong>addEventListener(&#39;message&#39;, ...)</strong>：监听主线程通过 postMessage 发送的消息。</li><li><strong>ev</strong>：事件对象，包含消息数据，可通过 ev.data 访问。</li><li><strong>false</strong>：表示事件监听器在冒泡阶段触发（默认设置，适用于大多数场景）。</li></ul><p><strong>3. 处理函数对象</strong> const handlers = { startTicks: (data) =&gt; { ticksInterval = setInterval(() =&gt; { self.postMessage({ type: &#39;tick&#39; }) }, data.delay) }, stopTicks: () =&gt; { clearInterval(ticksInterval) }}</p><ul><li><strong>handlers</strong>：一个对象，映射消息类型到对应的处理函数。 <ul><li><strong>startTicks</strong>：启动定时器的函数。 <ul><li><strong>参数</strong>：data（消息的负载，预期包含 delay 属性，表示定时器间隔时间，单位为毫秒）。</li><li><strong>功能</strong>：使用 setInterval 创建一个定时器，每隔 data.delay 毫秒向主线程发送 { type: &#39;tick&#39; } 消息。</li><li><strong>赋值</strong>：将 setInterval 返回的 ID 存储在 ticksInterval 中，以便后续停止定时器。</li></ul></li><li><strong>stopTicks</strong>：停止定时器的函数。 <ul><li><strong>功能</strong>：调用 clearInterval(ticksInterval) 清除由 ticksInterval 引用的定时器。</li></ul></li></ul></li></ul><p><strong>4. 消息处理逻辑</strong> if (handlers[ev.data.type]) { handlers<a href="./ev.data">ev.data.type</a>}</p><ul><li><strong>条件</strong>：检查消息的 type 属性（ev.data.type）是否在 handlers 对象中存在。</li><li><strong>操作</strong>：如果存在匹配的处理函数，则调用该函数，并将整个 ev.data 对象作为参数传递。</li></ul><p><strong>工作原理</strong></p><ol><li><strong>初始化</strong>： <ul><li>Worker 启动时，声明 ticksInterval 为 undefined。</li><li>设置 message 事件监听器，准备处理主线程发送的消息。</li></ul></li><li><strong>消息处理</strong>： <ul><li>主线程通过 postMessage 发送消息，Worker 接收后解析 ev.data。</li><li>消息预期是一个对象，包含 type 属性，例如 { type: &#39;startTicks&#39;, delay: 1000 } 或 { type: &#39;stopTicks&#39; }。</li></ul></li><li><strong>启动定时器</strong>： <ul><li>如果消息的 type 为 &#39;startTicks&#39;，则调用 startTicks 处理函数。</li><li>startTicks 使用 setInterval 创建定时器，每隔 data.delay 毫秒发送 { type: &#39;tick&#39; } 消息。</li><li>定时器 ID 存储在 ticksInterval 中。</li></ul></li><li><strong>停止定时器</strong>： <ul><li>如果消息的 type 为 &#39;stopTicks&#39;，则调用 stopTicks 处理函数。</li><li>stopTicks 使用 clearInterval(ticksInterval) 停止定时器。</li></ul></li><li><strong>通信</strong>： <ul><li>Worker 使用 self.postMessage 向主线程发送消息（例如 { type: &#39;tick&#39; }）。</li><li>主线程可以通过监听 message 事件接收这些消息。</li></ul></li></ol><p><strong>使用示例</strong> 以下是主线程如何与该 Worker 交互的示例代码： _// 创建 Web Worker_const worker = new Worker(&#39;worker.js&#39;); <em>// 假设代码在 worker.js 文件中</em> _// 监听 Worker 发送的消息_worker.onmessage = function(event) { if (event.data.type === &#39;tick&#39;) { console.log(&#39;收到 tick，时间：&#39;, new Date().toISOString()); }}; _// 启动定时器，间隔 1 秒_worker.postMessage({ type: &#39;startTicks&#39;, delay: 1000 }); _// 5 秒后停止定时器_setTimeout(() =&gt; { worker.postMessage({ type: &#39;stopTicks&#39; });}, 5000); <strong>运行效果</strong></p><ul><li>Worker 每隔 1 秒向主线程发送 { type: &#39;tick&#39; } 消息。</li><li>主线程收到消息后打印时间戳。</li><li>5 秒后，主线程发送 stopTicks 消息，Worker 停止定时器。</li></ul><p><strong>主要特性</strong></p><ol><li><strong>模块化</strong>：通过 handlers 对象组织处理函数，便于扩展新的消息类型。</li><li><strong>非阻塞</strong>：在 Web Worker 中运行定时器，不影响主线程的 UI 响应。</li><li><strong>简单通信</strong>：通过 postMessage 实现主线程与 Worker 的双向通信。</li><li><strong>动态配置</strong>：定时器间隔（delay）由主线程消息动态指定。</li></ol><p><strong>可能的改进</strong></p><ol><li><strong>错误处理</strong>： <ul><li>验证 data.delay 是否为正数。</li><li>处理重复调用 startTicks 的情况（例如，清除现有定时器）。</li><li>示例： startTicks: (data) =&gt; { if (typeof data.delay !== &#39;number&#39; || data.delay &lt;= 0) { self.postMessage({ type: &#39;error&#39;, message: &#39;无效的 delay 值&#39; }); return; } if (ticksInterval) clearInterval(ticksInterval); <em>// 清除已有定时器</em> ticksInterval = setInterval(() =&gt; { self.postMessage({ type: &#39;tick&#39; }) }, data.delay);}</li></ul></li><li><strong>扩展消息类型</strong>： <ul><li>添加 pauseTicks 或 resumeTicks 处理函数，实现暂停和恢复功能。</li><li>添加 getStatus 处理函数，返回定时器状态。</li></ul></li><li><strong>初始化检查</strong>： <ul><li>在 Worker 启动或终止时确保 ticksInterval 被清除。</li></ul></li><li><strong>调试支持</strong>： <ul><li>添加确认消息，例如发送 { type: &#39;started&#39; } 或 { type: &#39;stopped&#39; }。</li></ul></li></ol><p><strong>应用场景</strong></p><ul><li><strong>实时更新</strong>：定期更新 UI 元素，例如时钟或计数器。</li><li><strong>轮询</strong>：周期性检查新数据，例如轮询 API。</li><li><strong>动画</strong>：驱动动画或游戏循环，确保时间一致。</li><li><strong>后台任务</strong>：执行重复性后台任务，例如监控或日志记录。</li></ul><p><strong>局限性</strong></p><ol><li><strong>单一定时器</strong>：ticksInterval 只能保存一个定时器，重复调用 startTicks 会覆盖之前的定时器。</li><li><strong>无持久性</strong>：Worker 终止后，定时器状态会丢失。</li><li><strong>消息验证不足</strong>：未检查无效的 type 或缺少 delay 属性。</li><li><strong>全局变量</strong>：ticksInterval 是全局变量，在复杂 Worker 中可能引发问题。</li></ol><p><strong>总结</strong> 这段 Web Worker 脚本提供了一种简单高效的方式，用于管理一个周期性定时器，向主线程发送“tick”消息。它非常适合需要固定间隔且不阻塞 UI 的任务。通过 handlers 模式，代码结构清晰且易于扩展。稍加改进（例如错误处理、更多消息类型），即可适配更复杂的需求。</p></div>',1)])])}const v=e(i,[["render",a]]);export{d as __pageData,v as default};
